30	int main(int argc, char** argv) {
31	    fs::path out =
32	        (argc >= 2) ? fs::path(argv[1]) : fs::path("tests/unit/thesis_tiere/golden_fullpilot_320_binary_ids.txt");
33	
34	    auto               factory = std::make_shared<ex::ExperimentNodeFactory>();
35	    ex::ExperimentTree tree{factory};
36	    tree.build(tlz::catalog_static_levels<tlz::FullSourceCatalog>()); // nur statisch → reine binary_id-Quelle
37	    ex::StaticBinaryView const view = tree.static_binary_view();
38	
39	    std::vector<std::string> ids;
40	    ids.reserve(view.size());
41	    for (std::size_t i = 0; i < view.size(); ++i) ids.push_back(view[i].binary_id);
42	
43	    std::cout << "FullSourceCatalog binary_count = " << ids.size() << "\n";
44	    if (ids.size() != 320) {
45	        std::cerr << "ERWARTET 320 binary_ids (4*4*5*4), bekam " << ids.size() << " — ABBRUCH (keine golden-Datei).\n";
46	        return 1;
47	    }
48	
49	    std::ofstream f{out, std::ios::trunc};
50	    if (!f) {
51	        std::cerr << "kann golden-Datei nicht schreiben: " << out.string() << "\n";
52	        return 2;
53	    }
54	    f << "# GOLDEN-REFERENZ: 320 binary_ids des FullSourceCatalog (4*4*5*4) — STRANG A Inc4/S4a (2026-06-18).\n";
55	    f << "# EINGEFROREN. test_profile_roundtrip vergleicht den PROFIL-Pfad gegen DIESE Liste (Resume #139-Schutz).\n";
56	    f << "# Eine Zeile = ein binary_id (positions-getreue Reihenfolge des StaticBinaryView). NICHT neu generieren.\n";
57	    for (auto const& id : ids) f << id << "\n";
58	    f.close();
59	
60	    std::cout << "golden geschrieben: " << out.string() << "  (" << ids.size() << " binary_ids)\n";
61	    std::cout << "  golden[0]   = " << ids.front() << "\n";
62	    std::cout << "  golden[319] = " << ids.back() << "\n";
63	    return 0;
64	}
