44	    using CompositionFor = cea::CompositionFromPermTuple<PermT>;
45	    template <class Comp>
46	    using AnatomyFor = cea::SearchAlgorithmAnatomy<Comp>;
47	
48	    /// Die Achsen-Namen der Komposition-Slots (Reihenfolge T0..T18) — zentrale Pfad-Konvention (BR-2).
49	    [[nodiscard]] static constexpr std::array<std::string_view, 19> const& axis_names() noexcept {
50	        return kCompositionAxisNames;
51	    }
