61	    static constexpr cea::AnatomyGenus   genus      = cea::AnatomyGenus::Adapter;     // Tier-Unterklasse (Ebene 2)
62	    static constexpr cea::AnatomyGattung gattung    = cea::AnatomyGattung::Container; // Außen-Interface (Ebene 1)
63	    static constexpr std::size_t         slot_count = 13; // 12 geteilt/delegiert + inner_container
64	    static constexpr std::string_view    name       = "Adapter";
