66	    /// 12 geteilte/delegierte (§28) + inner_container (Inner defaultet auf DequeInner → stack/queue-Default, §26.4).
67	    template <class T0, class T1, class T2, class T3, class T4, class T5, class T6, class T7, class T8, class T9,
68	              class T10, class T11, class Inner = cea::DequeInner<>>
69	    using CompositionFor = cea::AdapterComposition<T0, T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11, Inner>;
70	    template <class Comp>
71	    using AnatomyFor = cea::AdapterAnatomy<Comp>;
72	
73	    [[nodiscard]] static constexpr std::array<std::string_view, 13> const& axis_names() noexcept {
74	        static constexpr std::array<std::string_view, 13> kNames = {
75	            "search_algo", "cache_traversal",  "memory_layout",  "allocator",    "prefetch",
76	            "concurrency", "serialization",    "telemetry",      "value_handle", "isa",
